// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The culture of a company: a strip of three pictures, the heading, a few figures and the values. Axes: layout
 * (split: the pictures beside the text, stacked: the pictures under it), tone, density.
 */
import { type ReactNode } from "react";
import { Box, Grid, Group, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Stat } from "./stats-band.types";
import type { Feature } from "./feature-grid.types";

export type AboutCompanyProps = {
  id: string;
  title: string;
  lead?: string;
  stats: Stat[];
  values: Feature[];
  layout?: "split" | "stacked";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function AboutCompany({
  id,
  title,
  lead = "",
  stats,
  values,
  layout = "split",
  tone = "default",
  density = "default",
  landmarkLabel,
}: AboutCompanyProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      lead={lead}
      tone={tone}
      density={density}
      layout={(((layout as string) === "split") ? "split" : "stack")}
      media={{ show: true, side: "start" }}
      landmarkLabel={landmarkLabel}
      aside={(
        <Box className="grid grid-cols-3 gap-4" data-testid="strip">
          <MediaFrame alt={title} ratio="3/4" />
          <MediaFrame alt={title} ratio="3/4" className="mt-8" />
          <MediaFrame alt={title} ratio="3/4" />
        </Box>
      )}
    >
      {((stats?.length ?? 0) > 0) ? (
        <Grid cols="2-4" className="gap-4" data-testid="stats">
          {(stats ?? []).map((s) => (
            <Stack key={s.id} gap="0" data-testid="stat">
              <Text size="3xl" weight="bold">
                {s.value}
              </Text>
              <Text size="xs" className="text-muted-foreground">
                {s.label}
              </Text>
            </Stack>
          ))}
        </Grid>
      ) : null}
      {((values?.length ?? 0) > 0) ? (
        <Box
          className={cn(
            "grid grid-cols-1 gap-4",
            (((layout as string) === "stacked") ? "md:grid-cols-3" : "")
          )}
          data-testid="values"
        >
          {(values ?? []).map((v) => (
            <Group key={v.id} gap="4" align="start" className="border-t border-border pt-4" data-testid="value">
              <LucideIcon name={v.icon} size={20} />
              <Stack gap="2">
                <Text size="sm" weight="semibold">
                  {v.title}
                </Text>
                <Text size="sm" className="text-muted-foreground">
                  {v.text}
                </Text>
              </Stack>
            </Group>
          ))}
        </Box>
      ) : null}
    </SectionFrame>
  );
}
